CREATE TABLE assertion_probe ( id INTEGER PRIMARY KEY CHECK (id = 0), reason TEXT NOT NULL )
CREATE TABLE audit_events ( id TEXT PRIMARY KEY NOT NULL, actor_type TEXT NOT NULL CHECK (actor_type IN ('user', 'system', 'support', 'editorial', 'service')), actor_id TEXT, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, result TEXT NOT NULL CHECK (result IN ('success', 'failure', 'denied')), detail_class TEXT, created_at TEXT NOT NULL )
CREATE TABLE birth_calc_daily_usage ( user_id TEXT NOT NULL REFERENCES users(id), utc_date TEXT NOT NULL, reserved_calc_count INTEGER NOT NULL CHECK (reserved_calc_count BETWEEN 0 AND 50), last_reservation_hash TEXT NOT NULL CHECK (last_reservation_hash GLOB 'sha256:[0-9a-f]*' AND length(last_reservation_hash) = 71), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, utc_date) )
CREATE TABLE birth_calc_reservations ( user_id TEXT NOT NULL REFERENCES users(id), reservation_hash TEXT NOT NULL CHECK (reservation_hash GLOB 'sha256:[0-9a-f]*' AND length(reservation_hash) = 71), utc_date TEXT NOT NULL, claim_token_hash TEXT NOT NULL CHECK (claim_token_hash GLOB 'sha256:[0-9a-f]*' AND length(claim_token_hash) = 71), status TEXT NOT NULL CHECK (status IN ('pending', 'charged', 'denied')), created_at TEXT NOT NULL, charged_at TEXT, PRIMARY KEY (user_id, reservation_hash), CHECK ( (status = 'pending' AND charged_at IS NULL) OR (status = 'charged' AND charged_at IS NOT NULL) OR (status = 'denied' AND charged_at IS NULL) ) )
CREATE TABLE birth_profile_version_counters ( user_id TEXT PRIMARY KEY NOT NULL REFERENCES users(id), last_allocated_version INTEGER NOT NULL CHECK (last_allocated_version >= 0), updated_at TEXT NOT NULL )
CREATE TABLE birth_profiles ( user_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, accuracy TEXT NOT NULL CHECK (accuracy IN ('exact', 'approximate', 'unknown')), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'superseded', 'invalid')), timezone TEXT, payload_enc BLOB, payload_key_version INTEGER, payload_nonce TEXT, geocode_confidence TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, consent_id TEXT REFERENCES consents(id), PRIMARY KEY (user_id, version), CHECK ( status NOT IN ('pending', 'active') OR ( payload_enc IS NOT NULL AND payload_key_version IS NOT NULL AND payload_nonce IS NOT NULL ) ) )
CREATE TABLE chart_snapshots ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), profile_version INTEGER NOT NULL, fingerprint TEXT NOT NULL, contract_id TEXT NOT NULL, contract_version TEXT NOT NULL, container_digest TEXT NOT NULL, tzdb_version TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'superseded', 'invalid')), calculated_at TEXT NOT NULL, snapshot_json TEXT NOT NULL, birth_accuracy TEXT NOT NULL CHECK (birth_accuracy IN ('exact', 'approximate', 'unknown')), birth_enc BLOB NOT NULL, birth_key_version INTEGER NOT NULL, birth_nonce TEXT NOT NULL, snapshot_enc BLOB, snapshot_key_version INTEGER, snapshot_nonce TEXT, r2_uri TEXT, uncertainty_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (user_id, fingerprint), FOREIGN KEY (user_id, profile_version) REFERENCES birth_profiles(user_id, version) )
CREATE TABLE "codex_provider_jobs" ( id TEXT PRIMARY KEY NOT NULL CHECK ( length(id) = 38 AND substr(id, 1, 6) = 'cpjob_' AND substr(id, 7) NOT GLOB '*[^0-9a-f]*' ), pipeline TEXT NOT NULL CHECK (pipeline IN ('pattern', 'ontology', 'reading')), owner_id TEXT NOT NULL CHECK (length(owner_id) BETWEEN 1 AND 200), user_id TEXT REFERENCES users(id), pass TEXT NOT NULL CHECK ( pass IN ( 'planner', 'writer', 'verifier', 'generator', 'evaluator', 'publisher' ) ), stage_generation INTEGER NOT NULL CHECK (stage_generation >= 0), stage_attempt INTEGER NOT NULL CHECK (stage_attempt >= 0), request_hash TEXT NOT NULL, request_object_key TEXT NOT NULL UNIQUE CHECK ( length(request_object_key) BETWEEN 1 AND 1024 AND substr(request_object_key, 1, 20) = 'codex-provider-jobs/' ), request_envelope_hash TEXT NOT NULL, request_ciphertext_hash TEXT NOT NULL, request_key_id TEXT NOT NULL CHECK (length(request_key_id) BETWEEN 1 AND 128), request_nonce TEXT NOT NULL CHECK (length(request_nonce) BETWEEN 16 AND 128), request_byte_length INTEGER NOT NULL CHECK (request_byte_length >= 0), response_hash TEXT, response_object_key TEXT UNIQUE CHECK ( response_object_key IS NULL OR ( length(response_object_key) BETWEEN 1 AND 1024 AND substr(response_object_key, 1, 20) = 'codex-provider-jobs/' ) ), response_envelope_hash TEXT, response_ciphertext_hash TEXT, response_key_id TEXT CHECK ( response_key_id IS NULL OR length(response_key_id) BETWEEN 1 AND 128 ), response_nonce TEXT CHECK ( response_nonce IS NULL OR length(response_nonce) BETWEEN 16 AND 128 ), response_byte_length INTEGER CHECK ( response_byte_length IS NULL OR response_byte_length >= 0 ), model TEXT NOT NULL CHECK (length(model) BETWEEN 1 AND 200), reasoning_effort TEXT NOT NULL CHECK (reasoning_effort IN ('high', 'xhigh')), prompt_version TEXT NOT NULL CHECK (length(prompt_version) BETWEEN 1 AND 200), timeout_ms INTEGER NOT NULL CHECK (timeout_ms = 900000), daily_call_limit INTEGER NOT NULL CHECK (daily_call_limit > 0), status TEXT NOT NULL CHECK ( status IN ('pending', 'leased', 'completed', 'failed', 'cancelled') ), lease_token_hash TEXT, lease_expires_at TEXT CHECK ( lease_expires_at IS NULL OR unixepoch(lease_expires_at) IS NOT NULL ), provider_request_id TEXT CHECK ( provider_request_id IS NULL OR length(provider_request_id) BETWEEN 1 AND 200 ), input_tokens INTEGER CHECK (input_tokens IS NULL OR input_tokens >= 0), output_tokens INTEGER CHECK (output_tokens IS NULL OR output_tokens >= 0), failure_code TEXT CHECK ( failure_code IS NULL OR failure_code IN ( 'publisher_unavailable', 'publisher_output_invalid', 'publisher_refused', 'publisher_auth_failed', 'publisher_model_unavailable', 'publisher_budget_exhausted' ) ), safe_detail_code TEXT CHECK ( safe_detail_code IS NULL OR safe_detail_code IN ( 'request_timeout', 'network_error', 'rate_limited', 'provider_5xx', 'authentication_failed', 'model_not_available', 'provider_refusal', 'max_output_tokens_exhausted', 'missing_output_text', 'multiple_output_text', 'invalid_json', 'schema_mismatch', 'daily_call_limit_reached' ) ), available_at TEXT NOT NULL CHECK (unixepoch(available_at) IS NOT NULL), created_at TEXT NOT NULL CHECK (unixepoch(created_at) IS NOT NULL), updated_at TEXT NOT NULL CHECK (unixepoch(updated_at) IS NOT NULL), completed_at TEXT CHECK ( completed_at IS NULL OR unixepoch(completed_at) IS NOT NULL ), UNIQUE (pipeline, owner_id, pass, stage_generation, stage_attempt), UNIQUE ( pipeline, owner_id, pass, stage_generation, stage_attempt, request_hash ), UNIQUE (request_key_id, request_nonce), UNIQUE (response_key_id, response_nonce), CHECK ( (pipeline IN ('pattern', 'reading') AND user_id IS NOT NULL) OR (pipeline = 'ontology' AND user_id IS NULL) ), CHECK ( (pipeline = 'pattern' AND pass IN ('planner', 'writer', 'verifier')) OR (pipeline = 'ontology' AND pass IN ( 'planner', 'writer', 'verifier', 'generator', 'evaluator' )) OR (pipeline = 'reading' AND pass = 'publisher') ), CHECK (unixepoch(updated_at) >= unixepoch(created_at)), CHECK ( completed_at IS NULL OR unixepoch(completed_at) >= unixepoch(created_at) ), CHECK ( (failure_code IS NULL AND safe_detail_code IS NULL) OR (failure_code = 'publisher_unavailable' AND safe_detail_code IN ( 'request_timeout', 'network_error', 'rate_limited', 'provider_5xx' )) OR (failure_code = 'publisher_output_invalid' AND safe_detail_code IN ( 'max_output_tokens_exhausted', 'missing_output_text', 'multiple_output_text', 'invalid_json', 'schema_mismatch' )) OR (failure_code = 'publisher_refused' AND safe_detail_code = 'provider_refusal') OR (failure_code = 'publisher_auth_failed' AND safe_detail_code = 'authentication_failed') OR (failure_code = 'publisher_model_unavailable' AND safe_detail_code = 'model_not_available') OR (failure_code = 'publisher_budget_exhausted' AND safe_detail_code = 'daily_call_limit_reached') ), CHECK ( lease_token_hash IS NULL OR ( length(lease_token_hash) = 71 AND substr(lease_token_hash, 1, 7) = 'sha256:' AND substr(lease_token_hash, 8) NOT GLOB '*[^0-9a-f]*' ) ), CHECK ( length(request_hash) = 71 AND substr(request_hash, 1, 7) = 'sha256:' AND substr(request_hash, 8) NOT GLOB '*[^0-9a-f]*' ), CHECK ( length(request_envelope_hash) = 71 AND substr(request_envelope_hash, 1, 7) = 'sha256:' AND substr(request_envelope_hash, 8) NOT GLOB '*[^0-9a-f]*' ), CHECK ( length(request_ciphertext_hash) = 71 AND substr(request_ciphertext_hash, 1, 7) = 'sha256:' AND substr(request_ciphertext_hash, 8) NOT GLOB '*[^0-9a-f]*' ), CHECK ( response_hash IS NULL OR ( length(response_hash) = 71 AND substr(response_hash, 1, 7) = 'sha256:' AND substr(response_hash, 8) NOT GLOB '*[^0-9a-f]*' ) ), CHECK ( response_envelope_hash IS NULL OR ( length(response_envelope_hash) = 71 AND substr(response_envelope_hash, 1, 7) = 'sha256:' AND substr(response_envelope_hash, 8) NOT GLOB '*[^0-9a-f]*' ) ), CHECK ( response_ciphertext_hash IS NULL OR ( length(response_ciphertext_hash) = 71 AND substr(response_ciphertext_hash, 1, 7) = 'sha256:' AND substr(response_ciphertext_hash, 8) NOT GLOB '*[^0-9a-f]*' ) ), CHECK ( ( response_hash IS NULL AND response_object_key IS NULL AND response_envelope_hash IS NULL AND response_ciphertext_hash IS NULL AND response_key_id IS NULL AND response_nonce IS NULL AND response_byte_length IS NULL ) OR ( response_hash IS NOT NULL AND response_object_key IS NOT NULL AND response_envelope_hash IS NOT NULL AND response_ciphertext_hash IS NOT NULL AND response_key_id IS NOT NULL AND response_nonce IS NOT NULL AND response_byte_length IS NOT NULL ) ), CHECK ( ( status = 'pending' AND lease_token_hash IS NULL AND lease_expires_at IS NULL AND response_hash IS NULL AND provider_request_id IS NULL AND input_tokens IS NULL AND output_tokens IS NULL AND failure_code IS NULL AND safe_detail_code IS NULL AND completed_at IS NULL ) OR ( status = 'leased' AND lease_token_hash IS NOT NULL AND lease_expires_at IS NOT NULL AND response_hash IS NULL AND provider_request_id IS NULL AND input_tokens IS NULL AND output_tokens IS NULL AND failure_code IS NULL AND safe_detail_code IS NULL AND completed_at IS NULL ) OR ( status = 'completed' AND lease_token_hash IS NOT NULL AND lease_expires_at IS NOT NULL AND response_hash IS NOT NULL AND provider_request_id IS NOT NULL AND input_tokens IS NOT NULL AND output_tokens IS NOT NULL AND failure_code IS NULL AND safe_detail_code IS NULL AND completed_at IS NOT NULL ) OR ( status = 'failed' AND lease_token_hash IS NOT NULL AND lease_expires_at IS NOT NULL AND response_hash IS NULL AND provider_request_id IS NULL AND input_tokens IS NULL AND output_tokens IS NULL AND failure_code IS NOT NULL AND safe_detail_code IS NOT NULL AND completed_at IS NOT NULL ) OR ( status = 'cancelled' AND lease_token_hash IS NULL AND lease_expires_at IS NULL AND response_hash IS NULL AND provider_request_id IS NULL AND input_tokens IS NULL AND output_tokens IS NULL AND failure_code IS NULL AND safe_detail_code IS NULL AND completed_at IS NOT NULL ) ) )
CREATE TABLE codex_provider_response_uploads ( job_id TEXT NOT NULL REFERENCES codex_provider_jobs(id) ON DELETE CASCADE, lease_token_hash TEXT NOT NULL CHECK ( length(lease_token_hash) = 71 AND substr(lease_token_hash, 1, 7) = 'sha256:' AND substr(lease_token_hash, 8) NOT GLOB '*[^0-9a-f]*' ), object_key TEXT NOT NULL UNIQUE CHECK ( length(object_key) BETWEEN 1 AND 1024 AND substr(object_key, 1, 20) = 'codex-provider-jobs/' ), created_at TEXT NOT NULL CHECK (unixepoch(created_at) IS NOT NULL), PRIMARY KEY (job_id, lease_token_hash) )
CREATE TABLE connector_accounts ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), provider TEXT NOT NULL, provider_account_id TEXT, scopes_json TEXT NOT NULL DEFAULT '[]', token_ref TEXT, status TEXT NOT NULL DEFAULT 'connected' CHECK (status IN ( 'connected', 'needs_reauth', 'revoked', 'error' )), expires_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (user_id, provider, provider_account_id) )
CREATE TABLE "consents" ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK (kind IN ( 'account_processing', 'product_source', 'os_permission', 'oauth_scope', 'ai_synthesis', 'pattern_generation', 'research', 'model_training', 'export', 'support_access' )), status TEXT NOT NULL CHECK (status IN ('granted', 'denied', 'paused', 'revoked', 'expired', 'pending')), source_id TEXT, permission_tier INTEGER NOT NULL DEFAULT 0 CHECK (permission_tier BETWEEN 0 AND 4), allowed_uses_json TEXT NOT NULL DEFAULT '[]', scopes_json TEXT NOT NULL DEFAULT '[]', provider TEXT, connector_account_id TEXT, policy_version TEXT NOT NULL, ui_surface TEXT, granted_at TEXT, revoked_at TEXT, paused_at TEXT, expires_at TEXT, version INTEGER NOT NULL DEFAULT 1, supersedes_consent_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK (source_id IS NULL OR source_id NOT GLOB 'NO-*') )
CREATE TABLE content_release_pointer ( id INTEGER PRIMARY KEY CHECK (id = 1), active_version TEXT NOT NULL REFERENCES content_releases(version), updated_at TEXT NOT NULL )
CREATE TABLE content_releases ( version TEXT PRIMARY KEY NOT NULL, bundle_hash TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK (status IN ( 'submitted', 'active', 'rejected', 'superseded' )), r2_uri TEXT, approver_id TEXT NOT NULL, last_author_id TEXT NOT NULL, changelog TEXT NOT NULL, calc_contract_id TEXT, activated_at TEXT, rejected_at TEXT, rejection_reason_class TEXT, created_at TEXT NOT NULL, CHECK (approver_id <> last_author_id) )
CREATE TABLE context_signals ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), source_id TEXT NOT NULL, source_window TEXT, evidence_lane TEXT NOT NULL CHECK (evidence_lane IN ( 'celestial_facts', 'user_and_context', 'operational' )), allowed_uses_json TEXT NOT NULL, confidence TEXT NOT NULL, sensitivity TEXT NOT NULL, permission_state TEXT NOT NULL CHECK (permission_state IN ( 'active', 'paused', 'revoked', 'expired', 'never_granted' )), conflict_status TEXT NOT NULL DEFAULT 'none' CHECK (conflict_status IN ( 'none', 'conflict', 'superseded', 'unconfirmed' )), consent_id TEXT REFERENCES consents(id), freshness_status TEXT NOT NULL CHECK (freshness_status IN ('fresh', 'stale', 'expired', 'unknown')), observed_at TEXT NOT NULL, ingested_at TEXT NOT NULL, expires_at TEXT, value_encoding TEXT NOT NULL CHECK (value_encoding IN ('structured', 'encrypted')), value_json TEXT, value_enc BLOB, value_key_version INTEGER, value_nonce TEXT, labels_json TEXT NOT NULL DEFAULT '[]', provenance_json TEXT, supersedes_signal_id TEXT, normalized_hash TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, source_revision INTEGER NOT NULL DEFAULT 1 CHECK (source_revision >= 1), is_current INTEGER NOT NULL DEFAULT 1 CHECK (is_current IN (0, 1)), retention_expires_at TEXT, CHECK (source_id NOT GLOB 'NO-*'), CHECK ( ( value_encoding = 'structured' AND value_json IS NOT NULL AND value_enc IS NULL AND value_key_version IS NULL AND value_nonce IS NULL ) OR ( value_encoding = 'encrypted' AND value_enc IS NOT NULL AND value_key_version IS NOT NULL AND value_nonce IS NOT NULL AND value_json IS NULL ) ) )
CREATE TABLE context_source_permissions ( user_id TEXT NOT NULL REFERENCES users(id), source_id TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)), permission_state TEXT NOT NULL CHECK (permission_state IN ( 'active', 'paused', 'revoked', 'expired', 'never_granted' )), allowed_uses_json TEXT NOT NULL DEFAULT '[]', permission_tier INTEGER NOT NULL DEFAULT 0 CHECK (permission_tier BETWEEN 0 AND 4), consent_id TEXT REFERENCES consents(id), scopes_json TEXT NOT NULL DEFAULT '[]', connector_status TEXT, last_signal_id TEXT, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, source_id), CHECK (source_id NOT GLOB 'NO-*') )
CREATE TABLE crypto_kek_rewrap_campaigns ( id TEXT PRIMARY KEY NOT NULL CHECK (id GLOB 'ckc_[0-9a-f]*' AND length(id) = 36), singleton INTEGER NOT NULL DEFAULT 1 CHECK (singleton = 1), idempotency_hash TEXT NOT NULL UNIQUE, target_root_kek_id TEXT NOT NULL CHECK ( length(target_root_kek_id) BETWEEN 1 AND 64 AND target_root_kek_id NOT GLOB '*[^A-Za-z0-9._-]*' ), status TEXT NOT NULL CHECK (status IN ('running','blocked','completed')), total_count INTEGER NOT NULL CHECK (total_count >= 0), completed_count INTEGER NOT NULL DEFAULT 0 CHECK (completed_count >= 0), blocked_count INTEGER NOT NULL DEFAULT 0 CHECK (blocked_count >= 0), revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0), lease_token_hash TEXT, lease_expires_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT, CHECK ( (lease_token_hash IS NULL AND lease_expires_at IS NULL) OR (lease_token_hash IS NOT NULL AND lease_expires_at IS NOT NULL) ) )
CREATE TABLE crypto_kek_rewrap_items ( campaign_id TEXT NOT NULL REFERENCES crypto_kek_rewrap_campaigns(id), user_id TEXT NOT NULL REFERENCES users(id), source_root_kek_id TEXT NOT NULL CHECK ( length(source_root_kek_id) BETWEEN 1 AND 64 AND source_root_kek_id NOT GLOB '*[^A-Za-z0-9._-]*' ), status TEXT NOT NULL CHECK (status IN ('pending','succeeded','blocked')), error_class TEXT, updated_at TEXT NOT NULL, PRIMARY KEY (campaign_id, user_id) )
CREATE TABLE crypto_operations ( id TEXT PRIMARY KEY NOT NULL CHECK (id GLOB 'cop_[0-9a-f]*' AND length(id) = 36), kind TEXT NOT NULL CHECK (kind = 'dek_rotate'), user_id TEXT NOT NULL REFERENCES users(id), idempotency_hash TEXT NOT NULL, stage TEXT NOT NULL CHECK (stage IN ( 'quiescing', 'reencrypting', 'finalizing', 'verifying', 'blocked', 'succeeded', 'failed', 'abandoned_to_deletion' )), original_account_status TEXT NOT NULL CHECK ( original_account_status IN ('active', 'frozen') ), previous_key_version INTEGER, candidate_key_version INTEGER, candidate_wrapped_dek BLOB, candidate_root_kek_id TEXT, reencrypted_count INTEGER NOT NULL DEFAULT 0 CHECK (reencrypted_count >= 0), revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0), lease_token_hash TEXT, lease_expires_at TEXT, not_before TEXT NOT NULL, error_class TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT, UNIQUE (kind, user_id, idempotency_hash), CHECK (stage != 'failed' OR reencrypted_count = 0), CHECK ( (lease_token_hash IS NULL AND lease_expires_at IS NULL) OR (lease_token_hash IS NOT NULL AND lease_expires_at IS NOT NULL) ), CHECK ( candidate_root_kek_id IS NULL OR ( length(candidate_root_kek_id) BETWEEN 1 AND 64 AND candidate_root_kek_id NOT GLOB '*[^A-Za-z0-9._-]*' ) ) )
CREATE TABLE cycle_instances ( id TEXT PRIMARY KEY NOT NULL, chart_id TEXT NOT NULL REFERENCES chart_snapshots(id), user_id TEXT NOT NULL REFERENCES users(id), technique TEXT NOT NULL, phase TEXT CHECK (phase IS NULL OR phase IN ( 'emerging', 'building', 'peak', 'reconsidering', 'integrating' )), body TEXT, target TEXT, aspect TEXT, start_at TEXT, exact_at TEXT, end_at TEXT, orb_deg REAL, importance_score REAL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed', 'superseded')), horizon_version TEXT, cycle_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL , pass_count INTEGER NOT NULL DEFAULT 1)
CREATE TABLE cycle_passes ( id TEXT PRIMARY KEY NOT NULL, cycle_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), pass_index INTEGER NOT NULL CHECK (pass_index >= 1), direction TEXT NOT NULL CHECK (direction IN ('direct', 'retrograde')), exact_at TEXT NOT NULL, speed_deg_per_day REAL NOT NULL, created_at TEXT NOT NULL, UNIQUE (cycle_id, pass_index), FOREIGN KEY (cycle_id, user_id) REFERENCES cycle_instances(id, user_id) )
CREATE TABLE cycle_scan_receipts ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, chart_id TEXT NOT NULL REFERENCES chart_snapshots(id) ON DELETE CASCADE, chart_fingerprint TEXT NOT NULL, local_date TEXT NOT NULL, scheduling_timezone TEXT NOT NULL, window_from TEXT NOT NULL, window_to TEXT NOT NULL, tzdb_version TEXT NOT NULL, local_day_resolution_policy_version TEXT NOT NULL, contract_id TEXT NOT NULL, contract_version TEXT NOT NULL, cycle_policy_id TEXT NOT NULL, cycle_policy_version TEXT NOT NULL, orb_policy_id TEXT NOT NULL, orb_policy_version TEXT NOT NULL, receipt_epoch INTEGER NOT NULL CHECK (receipt_epoch > 0), container_version TEXT NOT NULL, ephemeris_data_version TEXT NOT NULL, semantic_request_hash TEXT NOT NULL, semantic_result_hash TEXT NOT NULL, raw_response_sha256 TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL, CHECK (window_from < window_to), UNIQUE (id, user_id) )
CREATE TABLE daily_publication_receipts ( receipt_id TEXT PRIMARY KEY NOT NULL CHECK ( length(receipt_id) = 36 AND substr(receipt_id, 1, 4) = 'dpr_' AND substr(receipt_id, 5) NOT GLOB '*[^0-9a-f]*' ), reading_id TEXT NOT NULL UNIQUE CHECK (length(reading_id) BETWEEN 1 AND 64), job_id TEXT NOT NULL CHECK (length(job_id) BETWEEN 1 AND 64), command_generation INTEGER NOT NULL CHECK (command_generation >= 0), provider TEXT NOT NULL CHECK (provider = 'codex'), provider_job_id TEXT NOT NULL CHECK ( length(provider_job_id) = 38 AND substr(provider_job_id, 1, 6) = 'cpjob_' AND substr(provider_job_id, 7) NOT GLOB '*[^0-9a-f]*' ), stage_generation INTEGER NOT NULL CHECK (stage_generation >= 0), stage_attempt INTEGER NOT NULL CHECK (stage_attempt >= 0), model TEXT NOT NULL CHECK (length(model) BETWEEN 1 AND 200), reasoning_effort TEXT NOT NULL CHECK (reasoning_effort IN ('high', 'xhigh')), prompt_version TEXT NOT NULL CHECK (length(prompt_version) BETWEEN 1 AND 200), request_hash TEXT NOT NULL CHECK ( length(request_hash) = 71 AND substr(request_hash, 1, 7) = 'sha256:' AND substr(request_hash, 8) NOT GLOB '*[^0-9a-f]*' ), response_hash TEXT NOT NULL CHECK ( length(response_hash) = 71 AND substr(response_hash, 1, 7) = 'sha256:' AND substr(response_hash, 8) NOT GLOB '*[^0-9a-f]*' ), input_tokens INTEGER NOT NULL CHECK (input_tokens >= 0), output_tokens INTEGER NOT NULL CHECK (output_tokens >= 0), provider_completed_at TEXT NOT NULL CHECK (unixepoch(provider_completed_at) IS NOT NULL), worker_version_id TEXT NOT NULL CHECK ( length(worker_version_id) = 36 AND substr(worker_version_id, 9, 1) = '-' AND substr(worker_version_id, 14, 1) = '-' AND substr(worker_version_id, 19, 1) = '-' AND substr(worker_version_id, 24, 1) = '-' AND length(replace(worker_version_id, '-', '')) = 32 AND replace(worker_version_id, '-', '') NOT GLOB '*[^0-9a-f]*' ), release_git_sha TEXT NOT NULL CHECK ( length(release_git_sha) = 40 AND release_git_sha NOT GLOB '*[^0-9a-f]*' ), published_at TEXT NOT NULL CHECK (unixepoch(published_at) IS NOT NULL) , qualitative_findings_json TEXT NOT NULL DEFAULT '[]' CHECK ( json_valid(qualitative_findings_json) AND json_type(qualitative_findings_json) = 'array' ))
CREATE TABLE daily_readings ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), local_date TEXT NOT NULL, release_version TEXT REFERENCES content_releases(version), reading_key TEXT NOT NULL, chart_fingerprint TEXT NOT NULL, contract_id TEXT NOT NULL, assembly_mode TEXT NOT NULL CHECK (assembly_mode IN ('deterministic', 'constrained_model')), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'published', 'failed', 'superseded', 'invalidated')), revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1), revision_reason TEXT NOT NULL DEFAULT 'initial' CHECK (revision_reason IN ( 'initial', 'chart_recalculated', 'consent_revoked', 'safety_correction', 'defect_repair' )), supersedes_reading_id TEXT REFERENCES daily_readings(id), command_generation INTEGER NOT NULL DEFAULT 1 CHECK (command_generation >= 1), active_generation_job_id TEXT, invalidated_at TEXT, reading_enc BLOB, reading_key_version INTEGER, reading_nonce TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (reading_key), UNIQUE (user_id, local_date, revision), UNIQUE (id, user_id), CHECK ( (assembly_mode = 'constrained_model' AND release_version IS NULL) OR (assembly_mode = 'deterministic' AND release_version IS NOT NULL) ), CHECK ( (assembly_mode = 'constrained_model' AND reading_key LIKE 'reading-v5:%') OR (assembly_mode = 'deterministic' AND reading_key NOT LIKE 'reading-v5:%') ), CHECK ( status NOT IN ('published', 'invalidated') OR ( reading_enc IS NOT NULL AND reading_key_version IS NOT NULL AND reading_nonce IS NOT NULL ) ), CHECK ( (status = 'invalidated' AND invalidated_at IS NOT NULL) OR (status != 'invalidated' AND invalidated_at IS NULL) ), CHECK ( (revision_reason = 'initial' AND revision = 1 AND supersedes_reading_id IS NULL) OR (revision_reason != 'initial' AND revision > 1 AND supersedes_reading_id IS NOT NULL) ), FOREIGN KEY (active_generation_job_id, user_id) REFERENCES jobs(id, user_id) )
CREATE TABLE deletion_requests ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ( 'queued', 'running', 'completed', 'failed' )), dek_destroyed INTEGER NOT NULL DEFAULT 0 CHECK (dek_destroyed IN (0, 1)), idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT, job_id TEXT, receipt_hash TEXT CHECK (receipt_hash IS NULL OR length(receipt_hash) = 64), receipt_expires_at TEXT, checkpoint TEXT CHECK ( checkpoint IS NULL OR checkpoint IN ( 'accepted', 'exports_fenced', 'objects_deleted', 'rows_deleted', 'keys_erased', 'completed' ) ), status_updated_at TEXT, error_class TEXT, artifact_manifest_json TEXT NOT NULL DEFAULT '[]', artifact_cleanup_until TEXT, UNIQUE (user_id, idempotency_key) )
CREATE TABLE device_tokens ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), platform TEXT NOT NULL CHECK (platform IN ('ios', 'android', 'web')), token_hash TEXT NOT NULL, permission_status TEXT NOT NULL DEFAULT 'unknown', created_at TEXT NOT NULL, last_seen_at TEXT, UNIQUE (user_id, token_hash) )
CREATE TABLE export_requests ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ( 'queued', 'running', 'ready', 'failed', 'expired' )), r2_uri TEXT, expires_at TEXT, idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT, job_id TEXT, wrapped_export_key BLOB, export_key_nonce TEXT, export_kek_version INTEGER CHECK (export_kek_version IS NULL OR export_kek_version > 0), artifact_nonce TEXT, object_size_bytes INTEGER CHECK (object_size_bytes IS NULL OR object_size_bytes >= 0), status_updated_at TEXT, error_class TEXT, artifact_deleted_at TEXT, UNIQUE (user_id, idempotency_key) )
CREATE TABLE identities ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), provider TEXT NOT NULL, provider_subject TEXT NOT NULL, created_at TEXT NOT NULL, last_login_at TEXT, UNIQUE (provider, provider_subject) )
CREATE TABLE "jobs" ( id TEXT PRIMARY KEY NOT NULL, job_type TEXT NOT NULL, user_id TEXT REFERENCES users(id), idempotency_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'cancelled')), payload_json TEXT, payload_enc BLOB, payload_key_version INTEGER, payload_nonce TEXT, result_class TEXT, attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT, started_at TEXT, finished_at TEXT, dispatched_at TEXT, claim_token TEXT, lease_expires_at TEXT, created_at TEXT NOT NULL, CHECK (payload_enc IS NULL OR user_id IS NOT NULL), CHECK ( (payload_enc IS NULL AND payload_key_version IS NULL AND payload_nonce IS NULL) OR (payload_enc IS NOT NULL AND payload_key_version IS NOT NULL AND payload_nonce IS NOT NULL) ) )
CREATE TABLE natal_feature_sets ( id TEXT NOT NULL, chart_id TEXT NOT NULL REFERENCES chart_snapshots(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, feature_policy_id TEXT NOT NULL, feature_policy_version TEXT NOT NULL, feature_set_hash TEXT NOT NULL, feature_count INTEGER NOT NULL CHECK (feature_count >= 0), created_at TEXT NOT NULL, PRIMARY KEY (id, user_id) )
CREATE TABLE "natal_features" ( id TEXT NOT NULL, chart_id TEXT NOT NULL REFERENCES chart_snapshots(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, feature_type TEXT NOT NULL CHECK (feature_type IN ( 'position', 'aspect', 'pattern', 'angle', 'house_cusp', 'other' )), body_a TEXT, body_b TEXT, aspect TEXT, feature_json TEXT NOT NULL, orb_policy_id TEXT, orb_policy_version TEXT, created_at TEXT NOT NULL, feature_policy_id TEXT, feature_policy_version TEXT, feature_set_hash TEXT, PRIMARY KEY (id, user_id, chart_id) )
CREATE TABLE pattern_admin_access_events ( id TEXT PRIMARY KEY NOT NULL, admin_subject TEXT NOT NULL, target_user_id TEXT, target_scope_hash TEXT NOT NULL, generation_id TEXT NOT NULL, purpose_class TEXT NOT NULL CHECK (purpose_class IN ( 'quality_review', 'safety_investigation', 'incident_response', 'retention_audit' )), artifact_classes_json TEXT NOT NULL, result TEXT NOT NULL CHECK (result IN ('granted', 'denied', 'not_found', 'expired')), created_at TEXT NOT NULL )
CREATE TABLE pattern_admin_sessions ( id TEXT PRIMARY KEY NOT NULL, token_hash TEXT NOT NULL UNIQUE CHECK ( length(token_hash) = 71 AND substr(token_hash, 1, 7) = 'sha256:' AND substr(token_hash, 8) NOT GLOB '*[^0-9a-f]*' ), admin_subject TEXT NOT NULL CHECK (length(admin_subject) BETWEEN 1 AND 512), role TEXT NOT NULL CHECK (role = 'pattern_generation_auditor'), audience TEXT NOT NULL CHECK (length(audience) BETWEEN 1 AND 512), access_expires_at TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, revoked_at TEXT, CHECK (expires_at <= access_expires_at), CHECK (revoked_at IS NULL OR revoked_at >= created_at) )
CREATE TABLE pattern_documents ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), claim_id TEXT NOT NULL UNIQUE REFERENCES pattern_generation_claims(id), generation_id TEXT NOT NULL UNIQUE REFERENCES pattern_generation_jobs(generation_id), chart_fingerprint_hash TEXT NOT NULL, ontology_version TEXT NOT NULL, ontology_bundle_hash TEXT NOT NULL, locale TEXT NOT NULL, effective_accuracy TEXT NOT NULL, document_enc BLOB NOT NULL, document_nonce TEXT NOT NULL, wrapped_document_key_enc BLOB NOT NULL, wrapped_document_key_version INTEGER NOT NULL, wrapped_document_key_nonce TEXT NOT NULL, content_hash TEXT NOT NULL, compact_provenance_json TEXT NOT NULL, pattern_source_hash TEXT NOT NULL CHECK ( length(pattern_source_hash) = 71 AND substr(pattern_source_hash, 1, 7) = 'sha256:' AND substr(pattern_source_hash, 8) NOT GLOB '*[^0-9a-f]*' ), generated_at TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (user_id) )
CREATE TABLE pattern_erasure_replay_events ( event_id TEXT PRIMARY KEY NOT NULL CHECK (event_id GLOB 'prel_*' AND length(event_id) = 37), event_class TEXT NOT NULL CHECK (event_class IN ( 'claim_consumed', 'pattern_deleted', 'chart_correction_erased', 'pattern_withdrawn', 'ontology_recalled', 'account_deleted', 'pattern_regenerated' )), occurred_at TEXT NOT NULL, target_user_id TEXT, chart_fingerprint_hash TEXT, claim_id TEXT, generation_id TEXT, pattern_id TEXT, replacement_generation_id TEXT, replacement_pattern_id TEXT, ontology_version TEXT, prior_claim_status TEXT CHECK ( prior_claim_status IS NULL OR prior_claim_status IN ( 'available', 'reserved', 'accepted', 'deleted', 'superseded', 'withdrawn' ) ), next_claim_status TEXT, pattern_source_hash TEXT CHECK ( pattern_source_hash IS NULL OR ( length(pattern_source_hash) = 71 AND substr(pattern_source_hash, 1, 7) = 'sha256:' AND substr(pattern_source_hash, 8) NOT GLOB '*[^0-9a-f]*' ) ), content_hash TEXT NOT NULL CHECK (content_hash GLOB 'sha256:*' AND length(content_hash) = 71), signing_key_id TEXT NOT NULL CHECK (length(signing_key_id) BETWEEN 1 AND 128), signature TEXT NOT NULL, replica_put_at TEXT NOT NULL, created_at TEXT NOT NULL, CHECK ((event_class = 'ontology_recalled') = (next_claim_status IS NULL)), CHECK ( event_class != 'ontology_recalled' OR (ontology_version IS NOT NULL AND length(ontology_version) > 0) ), CHECK ( ( event_class = 'ontology_recalled' AND next_claim_status IS NULL ) OR ( event_class = 'claim_consumed' AND next_claim_status IN ('accepted', 'deleted', 'superseded', 'withdrawn') ) OR ( event_class IN ('pattern_deleted', 'account_deleted') AND next_claim_status = 'deleted' ) OR ( event_class = 'chart_correction_erased' AND next_claim_status = 'superseded' ) OR ( event_class = 'pattern_withdrawn' AND next_claim_status = 'withdrawn' ) OR ( event_class = 'pattern_regenerated' AND prior_claim_status = 'accepted' AND next_claim_status = 'accepted' ) ), CHECK (event_class = 'ontology_recalled' 