_report_hash IS NOT NULL ), CHECK ( stage NOT IN ('regressing', 'signing', 'ingesting', 'succeeded') OR evaluation_report_hash IS NOT NULL ), CHECK ( stage NOT IN ('signing', 'ingesting', 'succeeded') OR regression_report_hash IS NOT NULL ), CHECK ( stage NOT IN ('ingesting', 'succeeded') OR bundle_hash IS NOT NULL ), CHECK ( ( stage = 'succeeded' AND failure_class IS NULL AND claim_token IS NULL AND lease_expires_at IS NULL AND failed_artifact_expires_at IS NULL AND finished_at IS NOT NULL AND succeeded_at IS NOT NULL AND failed_at IS NULL AND dispatched_at IS NOT NULL AND unixepoch(finished_at) IS NOT NULL AND unixepoch(succeeded_at) IS NOT NULL AND finished_at = succeeded_at AND unixepoch(finished_at) >= unixepoch(created_at) ) OR ( stage = 'failed' AND failure_class IS NOT NULL AND claim_token IS NULL AND lease_expires_at IS NULL AND failed_artifact_expires_at IS NOT NULL AND finished_at IS NOT NULL AND succeeded_at IS NULL AND failed_at IS NOT NULL AND dispatched_at IS NOT NULL AND unixepoch(finished_at) IS NOT NULL AND unixepoch(failed_at) IS NOT NULL AND unixepoch(failed_artifact_expires_at) IS NOT NULL AND finished_at = failed_at AND unixepoch(finished_at) >= unixepoch(created_at) AND unixepoch(failed_artifact_expires_at) - unixepoch(failed_at) = 604800 ) OR ( stage NOT IN ('succeeded', 'failed') AND failure_class IS NULL AND failed_artifact_expires_at IS NULL AND finished_at IS NULL AND succeeded_at IS NULL AND failed_at IS NULL ) ) )
CREATE TABLE pattern_ontology_pointer ( id INTEGER PRIMARY KEY CHECK (id = 1), active_version TEXT REFERENCES pattern_ontology_releases(version), updated_at TEXT NOT NULL )
CREATE TABLE pattern_ontology_provider_daily_usage ( utc_date TEXT PRIMARY KEY NOT NULL, used_calls INTEGER NOT NULL DEFAULT 0 CHECK (used_calls >= 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL , generator_calls INTEGER NOT NULL DEFAULT 0 CHECK (generator_calls >= 0), evaluator_calls INTEGER NOT NULL DEFAULT 0 CHECK (evaluator_calls >= 0), regression_calls INTEGER NOT NULL DEFAULT 0 CHECK (regression_calls >= 0))
CREATE TABLE pattern_ontology_recall_events ( id TEXT PRIMARY KEY NOT NULL, ontology_version TEXT NOT NULL REFERENCES pattern_ontology_releases(version), reason_class TEXT NOT NULL, created_at TEXT NOT NULL )
CREATE TABLE pattern_ontology_releases ( version TEXT PRIMARY KEY NOT NULL, bundle_hash TEXT NOT NULL UNIQUE, corpus_release_hash TEXT NOT NULL, locale TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('candidate', 'active', 'superseded', 'recalled')), object_key TEXT NOT NULL, evaluation_json TEXT NOT NULL, created_at TEXT NOT NULL, recalled_at TEXT )
CREATE TABLE "pattern_portrait_assets" ( id TEXT PRIMARY KEY, portrait_id TEXT NOT NULL REFERENCES "pattern_portraits"(id), user_id TEXT NOT NULL REFERENCES users(id), job_id TEXT REFERENCES "pattern_portrait_jobs"(id), role TEXT NOT NULL CHECK (role IN ('image','sample','graph')), object_key TEXT NOT NULL UNIQUE CHECK (object_key LIKE 'pattern-portraits/%'), plaintext_sha256 TEXT NOT NULL, byte_length INTEGER NOT NULL CHECK (byte_length > 0 AND byte_length <= 3145728), created_at TEXT NOT NULL, cleanup_at TEXT, deleted_at TEXT )
