CREATE TABLE "pattern_portraits" ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), pattern_id TEXT NOT NULL UNIQUE, generation_id TEXT NOT NULL, chart_id TEXT NOT NULL, chart_fingerprint_hash TEXT NOT NULL, document_revision TEXT NOT NULL, document_hash TEXT NOT NULL, generated_at TEXT NOT NULL, ontology_version TEXT NOT NULL, processing_consent_id TEXT NOT NULL, pattern_consent_id TEXT NOT NULL, consent_policy_version TEXT NOT NULL CHECK (consent_policy_version IN ('1.0.0','2.0.0')), sun_sign TEXT, status TEXT NOT NULL CHECK (status IN ('generating','failed','ready','cancelled')), graph_asset_id TEXT, checked_at TEXT NOT NULL DEFAULT '1970-01-01T00:00:00.000Z', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, chapter_count INTEGER NOT NULL DEFAULT 4 CHECK (typeof(chapter_count) = 'integer' AND chapter_count BETWEEN 3 AND 6), protocol_version TEXT NOT NULL DEFAULT 'v1' CHECK (protocol_version IN ('v1','v2')), CHECK ((protocol_version = 'v1' AND chapter_count = 4 AND consent_policy_version = '1.0.0') OR (protocol_version = 'v2' AND consent_policy_version = '2.0.0')) )
CREATE TABLE pattern_provider_daily_usage ( utc_date TEXT PRIMARY KEY NOT NULL, used_calls INTEGER NOT NULL DEFAULT 0 CHECK (used_calls >= 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL , planner_calls INTEGER NOT NULL DEFAULT 0 CHECK (planner_calls >= 0), writer_calls INTEGER NOT NULL DEFAULT 0 CHECK (writer_calls >= 0), verifier_calls INTEGER NOT NULL DEFAULT 0 CHECK (verifier_calls >= 0))
CREATE TABLE pattern_source_corpus_releases ( corpus_release_id TEXT PRIMARY KEY NOT NULL CHECK (length(corpus_release_id) BETWEEN 1 AND 200), corpus_hash TEXT NOT NULL, locale TEXT NOT NULL CHECK (length(locale) BETWEEN 2 AND 35), object_key TEXT NOT NULL UNIQUE CHECK (length(object_key) BETWEEN 1 AND 1024), fragment_count INTEGER NOT NULL CHECK (fragment_count > 0), license_class TEXT NOT NULL CHECK (license_class IN ('licensed_excerpt', 'internal_synthetic')), public_capable INTEGER NOT NULL CHECK (public_capable IN (0, 1)), created_at TEXT NOT NULL CHECK (unixepoch(created_at) IS NOT NULL), registered_at TEXT NOT NULL CHECK (unixepoch(registered_at) IS NOT NULL), UNIQUE (corpus_release_id, corpus_hash), UNIQUE (corpus_hash), CHECK ( length(corpus_hash) = 71 AND substr(corpus_hash, 1, 7) = 'sha256:' AND substr(corpus_hash, 8) NOT GLOB '*[^0-9a-f]*' ), CHECK ( (license_class = 'licensed_excerpt' AND public_capable = 1) OR (license_class = 'internal_synthetic' AND public_capable = 0) ), CHECK (unixepoch(registered_at) >= unixepoch(created_at)) )
CREATE TABLE "place_resolutions" ( id TEXT PRIMARY KEY NOT NULL CHECK (id GLOB 'plc_[0-9a-f]*' AND length(id) = 36), user_id TEXT NOT NULL REFERENCES users(id), provider TEXT NOT NULL CHECK (provider IN ('google_places_geocoding_v4', 'geoapify')), policy_version TEXT NOT NULL, payload_enc BLOB NOT NULL, payload_key_version INTEGER NOT NULL CHECK (payload_key_version >= 1), payload_nonce TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, consumed_at TEXT, UNIQUE (user_id, id) )
CREATE TABLE "portrait_automation_grants" ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), chart_id TEXT NOT NULL, chart_fingerprint_hash TEXT NOT NULL, policy_version TEXT NOT NULL CHECK(policy_version IN ('1.1.0','2.0.0')), enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL )
CREATE TABLE "portrait_mesh_assets" ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), portrait_id TEXT NOT NULL REFERENCES "pattern_portraits"(id), job_id TEXT NOT NULL REFERENCES "portrait_mesh_jobs"(id), role TEXT NOT NULL CHECK(role IN ('model','provenance')), object_key TEXT NOT NULL UNIQUE CHECK(object_key LIKE 'portrait-meshes/%'), plaintext_sha256 TEXT NOT NULL, byte_length INTEGER NOT NULL CHECK(byte_length>0 AND byte_length<=750000), created_at TEXT NOT NULL, cleanup_at TEXT, deleted_at TEXT )
CREATE TABLE "portrait_mesh_jobs" ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), portrait_id TEXT NOT NULL REFERENCES "pattern_portraits"(id), grant_id TEXT NOT NULL REFERENCES "portrait_automation_grants"(id), image_asset_id TEXT NOT NULL, processing_consent_id TEXT NOT NULL, pattern_consent_id TEXT NOT NULL, chapter_index INTEGER NOT NULL CHECK(typeof(chapter_index) = 'integer' AND chapter_index BETWEEN 0 AND 5), source_text_sha256 TEXT NOT NULL, source_image_sha256 TEXT NOT NULL, document_revision TEXT NOT NULL, compiler_version TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','running','complete','failed','cancelled')), attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3), lease_hash TEXT, lease_expires_at TEXT, retry_at TEXT NOT NULL, failure_code TEXT, completion_hash TEXT, model_asset_id TEXT, provenance_asset_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT, UNIQUE(portrait_id,chapter_index,compiler_version), CHECK(status!='running' OR (lease_hash IS NOT NULL AND lease_expires_at IS NOT NULL)), CHECK(status!='complete' OR (model_asset_id IS NOT NULL AND provenance_asset_id IS NOT NULL AND completion_hash IS NOT NULL)) )
CREATE TABLE "portrait_start_outbox" ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), pattern_id TEXT NOT NULL UNIQUE, grant_id TEXT NOT NULL REFERENCES "portrait_automation_grants"(id), chart_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','complete','cancelled','unsupported')), checked_at TEXT NOT NULL DEFAULT '1970-01-01T00:00:00.000Z', created_at TEXT NOT NULL )
CREATE TABLE reader_relationship_supports ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), document_kind TEXT NOT NULL CHECK (document_kind IN ('daily', 'pattern')), document_id TEXT NOT NULL, reading_id TEXT, pattern_id TEXT, support_enc BLOB NOT NULL, support_key_version INTEGER NOT NULL, support_nonce TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (document_kind, document_id), CHECK ((document_kind = 'daily' AND reading_id IS NOT NULL AND reading_id = document_id AND pattern_id IS NULL) OR (document_kind = 'pattern' AND pattern_id IS NOT NULL AND pattern_id = document_id AND reading_id IS NULL)), FOREIGN KEY (reading_id, user_id) REFERENCES daily_readings(id, user_id) ON DELETE CASCADE, FOREIGN KEY (pattern_id, user_id) REFERENCES pattern_documents(id, user_id) ON DELETE CASCADE )
CREATE TABLE reading_feedback ( id TEXT PRIMARY KEY NOT NULL, reading_id TEXT NOT NULL REFERENCES daily_readings(id), user_id TEXT NOT NULL REFERENCES users(id), resonance TEXT CHECK (resonance IS NULL OR resonance IN ( 'helpful', 'neutral', 'not_helpful', 'off' )), relevance_labels_json TEXT NOT NULL DEFAULT '[]', notes_enc BLOB, notes_key_version INTEGER, notes_nonce TEXT, created_at TEXT NOT NULL, UNIQUE (reading_id, user_id, created_at) )
CREATE TABLE reading_feedback_events ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), reading_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, event_enc BLOB NOT NULL, event_key_version INTEGER NOT NULL, event_nonce TEXT NOT NULL, created_at TEXT NOT NULL, effect_expires_at TEXT, retention_expires_at TEXT NOT NULL, UNIQUE (user_id, idempotency_key), FOREIGN KEY (reading_id, user_id) REFERENCES daily_readings(id, user_id) ON DELETE CASCADE )
CREATE TABLE reading_provider_daily_usage ( utc_date TEXT PRIMARY KEY NOT NULL, used_calls INTEGER NOT NULL DEFAULT 0 CHECK (used_calls >= 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL )
CREATE TABLE reading_saves ( user_id TEXT NOT NULL REFERENCES users(id), reading_id TEXT NOT NULL, saved_at TEXT NOT NULL, PRIMARY KEY (user_id, reading_id), FOREIGN KEY (reading_id, user_id) REFERENCES daily_readings(id, user_id) )
CREATE TABLE reading_sources ( id TEXT PRIMARY KEY NOT NULL, reading_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), paragraph_id TEXT NOT NULL, paragraph_order INTEGER NOT NULL CHECK (paragraph_order >= 1), evidence_enc BLOB NOT NULL, evidence_key_version INTEGER NOT NULL, evidence_nonce TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (reading_id, paragraph_id), UNIQUE (reading_id, paragraph_order), FOREIGN KEY (reading_id, user_id) REFERENCES daily_readings(id, user_id) )
CREATE TABLE runtime_health_access_events ( id TEXT PRIMARY KEY NOT NULL, admin_subject TEXT NOT NULL CHECK(length(admin_subject) BETWEEN 1 AND 200), purpose_class TEXT NOT NULL CHECK(purpose_class='incident_response'), result TEXT NOT NULL CHECK(result IN ('granted','denied','unavailable')), created_at TEXT NOT NULL CHECK(julianday(created_at) IS NOT NULL), expires_at TEXT NOT NULL CHECK(julianday(expires_at)>julianday(created_at)) )
CREATE TABLE runtime_health_capture ( work_class TEXT PRIMARY KEY CHECK(work_class IN ('text','portrait','mesh')), started_at TEXT NOT NULL CHECK(julianday(started_at) IS NOT NULL) )
CREATE TABLE sessions ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), token_sha256 TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, last_seen_at TEXT, revoked_at TEXT )
CREATE TABLE time_travel_daily_usage ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, utc_date TEXT NOT NULL, reserved_scan_count INTEGER NOT NULL DEFAULT 0 CHECK (reserved_scan_count >= 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (user_id, utc_date) )
CREATE TABLE timezone_changes ( id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), previous_zone TEXT, next_zone TEXT NOT NULL, source TEXT NOT NULL CHECK (source IN ('default_unconfirmed', 'device_derived', 'user_confirmed')), revision INTEGER NOT NULL, changed_at TEXT NOT NULL, UNIQUE (user_id, revision) )
CREATE TABLE user_keys ( user_id TEXT NOT NULL REFERENCES users(id), key_version INTEGER NOT NULL DEFAULT 1, kek_version INTEGER NOT NULL DEFAULT 1, wrapped_dek BLOB, created_at TEXT NOT NULL, rotated_at TEXT, destroyed_at TEXT, erased_at TEXT, root_kek_id TEXT NOT NULL DEFAULT 'legacy' CHECK ( length(root_kek_id) BETWEEN 1 AND 64 AND root_kek_id NOT GLOB '*[^A-Za-z0-9._-]*' ), PRIMARY KEY (user_id, key_version), CHECK ( (destroyed_at IS NULL AND erased_at IS NULL AND wrapped_dek IS NOT NULL) OR (destroyed_at IS NOT NULL AND erased_at IS NULL AND wrapped_dek IS NOT NULL) OR (destroyed_at IS NOT NULL AND erased_at IS NOT NULL AND wrapped_dek IS NULL) ) )
CREATE TABLE users ( id TEXT PRIMARY KEY NOT NULL CHECK (id GLOB 'usr_*' AND id NOT GLOB '*:*'), crypto_subject TEXT NOT NULL UNIQUE CHECK (crypto_subject GLOB 'cs_*' AND crypto_subject NOT GLOB '*:*'), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'frozen', 'pending_deletion', 'deleted')), locale TEXT NOT NULL DEFAULT 'en-US', timezone TEXT NOT NULL DEFAULT 'UTC', entitlement_tier TEXT NOT NULL DEFAULT 'free', next_due_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT , timezone_source TEXT NOT NULL DEFAULT 'default_unconfirmed', timezone_revision INTEGER NOT NULL DEFAULT 0, timezone_updated_at TEXT, locale_source TEXT NOT NULL DEFAULT 'default_unconfirmed', locale_updated_at TEXT, crypto_write_fence TEXT CHECK ( crypto_write_fence IS NULL OR ( crypto_write_fence GLOB 'cop_[0-9a-f]*' AND length(crypto_write_fence) = 36 ) ))
