CREATE TRIGGER pattern_claim_pending_insert_guard BEFORE INSERT ON pattern_generation_claims FOR EACH ROW BEGIN SELECT (CASE WHEN NEW.pending_regeneration_id IS NOT NULL THEN RAISE(ABORT, 'new pattern claim cannot start with pending regeneration') END); END
CREATE TRIGGER pattern_claim_transition_guard BEFORE UPDATE ON pattern_generation_claims FOR EACH ROW BEGIN SELECT (CASE WHEN NOT ( NEW.status = OLD.status OR (OLD.status = 'available' AND NEW.status = 'reserved') OR (OLD.status = 'reserved' AND NEW.status = 'available') OR (OLD.status = 'reserved' AND NEW.status = 'accepted') OR ( OLD.status = 'accepted' AND NEW.status IN ('deleted', 'superseded', 'withdrawn') ) ) THEN RAISE(ABORT, 'illegal pattern claim transition') END); SELECT (CASE WHEN NEW.id IS NOT OLD.id OR NEW.user_id IS NOT OLD.user_id OR NEW.chart_fingerprint_hash IS NOT OLD.chart_fingerprint_hash OR NEW.created_at IS NOT OLD.created_at THEN RAISE(ABORT, 'pattern claim identity is immutable') END); SELECT (CASE WHEN OLD.status = 'reserved' AND NEW.status = 'accepted' AND (NEW.consumed_at IS NULL OR NEW.accepted_at IS NULL) THEN RAISE(ABORT, 'accepted pattern claim requires consumption timestamps') WHEN NOT (OLD.status = 'reserved' AND NEW.status = 'accepted') AND ( NEW.consumed_at IS NOT OLD.consumed_at OR NEW.accepted_at IS NOT OLD.accepted_at ) THEN RAISE(ABORT, 'pattern claim consumption is immutable') END); SELECT (CASE WHEN OLD.status = 'accepted' AND NEW.status = 'deleted' AND NEW.deleted_at IS NULL THEN RAISE(ABORT, 'deleted pattern claim requires deleted_at') WHEN NOT (OLD.status = 'accepted' AND NEW.status = 'deleted') AND NEW.deleted_at IS NOT OLD.deleted_at THEN RAISE(ABORT, 'pattern claim deleted_at is immutable') END); SELECT (CASE WHEN OLD.status = 'accepted' AND NEW.status = 'superseded' AND NEW.superseded_at IS NULL THEN RAISE(ABORT, 'superseded pattern claim requires superseded_at') WHEN NOT (OLD.status = 'accepted' AND NEW.status = 'superseded') AND NEW.superseded_at IS NOT OLD.superseded_at THEN RAISE(ABORT, 'pattern claim superseded_at is immutable') END); SELECT (CASE WHEN OLD.status = 'accepted' AND NEW.status = 'withdrawn' AND NEW.withdrawn_at IS NULL THEN RAISE(ABORT, 'withdrawn pattern claim requires withdrawn_at') WHEN NOT (OLD.status = 'accepted' AND NEW.status = 'withdrawn') AND NEW.withdrawn_at IS NOT OLD.withdrawn_at THEN RAISE(ABORT, 'pattern claim withdrawn_at is immutable') END); SELECT (CASE WHEN NEW.status = OLD.status AND NEW.active_generation_id IS NOT OLD.active_generation_id THEN RAISE(ABORT, 'same-state pattern claim cannot change generation owner') END); SELECT (CASE WHEN NEW.status != 'accepted' AND NEW.pending_regeneration_id IS NOT NULL THEN RAISE(ABORT, 'only accepted pattern claim may regenerate') WHEN OLD.status = 'accepted' AND NEW.status != 'accepted' AND OLD.pending_regeneration_id IS NOT NULL THEN RAISE(ABORT, 'pending pattern regeneration must finish before terminal transition') WHEN NEW.pending_regeneration_id IS NOT OLD.pending_regeneration_id AND NOT ( OLD.status = 'accepted' AND NEW.status = 'accepted' AND ( (OLD.pending_regeneration_id IS NULL AND NEW.pending_regeneration_id IS NOT NULL) OR (OLD.pending_regeneration_id IS NOT NULL AND NEW.pending_regeneration_id IS NULL) ) ) THEN RAISE(ABORT, 'illegal pattern regeneration owner transition') END); END
CREATE TRIGGER pattern_ontology_pipeline_artifacts_create_only BEFORE UPDATE ON pattern_ontology_pipeline_artifacts FOR EACH ROW WHEN NOT ( OLD.id IS NEW.id AND OLD.run_id IS NEW.run_id AND OLD.stage IS NEW.stage AND OLD.stage_generation IS NEW.stage_generation AND OLD.stage_attempt IS NEW.stage_attempt AND OLD.artifact_class IS NEW.artifact_class AND OLD.object_key IS NEW.object_key AND OLD.plaintext_sha256 IS NEW.plaintext_sha256 AND OLD.envelope_sha256 IS NEW.envelope_sha256 AND OLD.ciphertext_sha256 IS NEW.ciphertext_sha256 AND OLD.envelope_key_id IS NEW.envelope_key_id AND OLD.envelope_nonce IS NEW.envelope_nonce AND OLD.byte_length IS NEW.byte_length AND OLD.created_at IS NEW.created_at AND ( ( OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL AND unixepoch(NEW.deleted_at) <= unixepoch('now') AND OLD.expires_at IS NEW.expires_at ) OR ( OLD.expires_at IS NULL AND NEW.expires_at IS NOT NULL AND OLD.deleted_at IS NEW.deleted_at AND EXISTS ( SELECT 1 FROM pattern_ontology_pipeline_runs run WHERE run.run_id = OLD.run_id AND run.stage = 'failed' AND run.failed_artifact_expires_at IS NEW.expires_at ) ) ) ) BEGIN SELECT RAISE(ABORT, 'ontology pipeline artifact identity is create-only'); END
CREATE TRIGGER pattern_ontology_pipeline_artifacts_must_start_live BEFORE INSERT ON pattern_ontology_pipeline_artifacts FOR EACH ROW WHEN NEW.deleted_at IS NOT NULL BEGIN SELECT RAISE(ABORT, 'ontology pipeline artifact must enter live'); END
CREATE TRIGGER pattern_ontology_pipeline_artifacts_no_delete BEFORE DELETE ON pattern_ontology_pipeline_artifacts FOR EACH ROW BEGIN SELECT RAISE(ABORT, 'ontology pipeline artifact tombstone cannot be deleted'); END
CREATE TRIGGER pattern_ontology_pipeline_artifacts_no_early_expiry BEFORE INSERT ON pattern_ontology_pipeline_artifacts FOR EACH ROW WHEN NEW.expires_at IS NOT NULL BEGIN SELECT RAISE(ABORT, 'ontology pipeline artifact expiry is terminally assigned'); END
CREATE TRIGGER pattern_ontology_pipeline_artifacts_no_reuse BEFORE INSERT ON pattern_ontology_pipeline_artifacts FOR EACH ROW WHEN EXISTS ( SELECT 1 FROM pattern_ontology_pipeline_artifacts artifact WHERE artifact.id = NEW.id OR artifact.object_key = NEW.object_key OR ( artifact.run_id = NEW.run_id AND artifact.stage = NEW.stage AND artifact.stage_generation = NEW.stage_generation AND artifact.stage_attempt = NEW.stage_attempt AND artifact.artifact_class = NEW.artifact_class ) OR ( artifact.envelope_key_id = NEW.envelope_key_id AND artifact.envelope_nonce = NEW.envelope_nonce ) ) BEGIN SELECT RAISE(ABORT, 'ontology pipeline artifact identity cannot be reused'); END
CREATE TRIGGER pattern_ontology_pipeline_artifacts_stage_owner BEFORE INSERT ON pattern_ontology_pipeline_artifacts FOR EACH ROW WHEN NOT EXISTS ( SELECT 1 FROM pattern_ontology_pipeline_runs run WHERE run.run_id = NEW.run_id AND run.stage = NEW.stage AND run.stage_generation = NEW.stage_generation AND run.stage_attempt = NEW.stage_attempt AND unixepoch(NEW.created_at) >= unixepoch(run.created_at) AND unixepoch(NEW.created_at) <= unixepoch('now') ) BEGIN SELECT RAISE(ABORT, 'ontology pipeline artifact stage owner or creation time is stale'); END
CREATE TRIGGER pattern_ontology_pipeline_evidence_committed_immutable BEFORE UPDATE ON pattern_ontology_pipeline_evidence FOR EACH ROW WHEN OLD.evidence_status = 'committed' BEGIN SELECT RAISE(ABORT, 'committed ontology pipeline evidence is immutable'); END
CREATE TRIGGER pattern_ontology_pipeline_evidence_no_delete BEFORE DELETE ON pattern_ontology_pipeline_evidence FOR EACH ROW WHEN OLD.evidence_status = 'committed' BEGIN SELECT RAISE(ABORT, 'committed ontology pipeline evidence cannot be deleted'); END
CREATE TRIGGER pattern_ontology_pipeline_regression_evidence_insert_shape BEFORE INSERT ON pattern_ontology_pipeline_evidence FOR EACH ROW WHEN NOT ( ( NEW.regression_report_hash IS NULL AND NEW.regression_artifact_object_key IS NULL AND NEW.regression_artifact_envelope_hash IS NULL AND NEW.regression_artifact_ciphertext_hash IS NULL AND NEW.regression_artifact_stage_generation IS NULL AND NEW.regression_artifact_stage_attempt IS NULL ) OR ( NEW.regression_report_hash IS NOT NULL AND NEW.regression_artifact_object_key IS NOT NULL AND NEW.regression_artifact_envelope_hash IS NOT NULL AND NEW.regression_artifact_ciphertext_hash IS NOT NULL AND NEW.regression_artifact_stage_generation IS NOT NULL AND NEW.regression_artifact_stage_attempt IS NOT NULL ) ) BEGIN SELECT RAISE(ABORT, 'ontology regression evidence tuple must be complete'); END
CREATE TRIGGER pattern_ontology_pipeline_regression_evidence_update_shape BEFORE UPDATE ON pattern_ontology_pipeline_evidence FOR EACH ROW WHEN NOT ( ( NEW.regression_report_hash IS NULL AND NEW.regression_artifact_object_key IS NULL AND NEW.regression_artifact_envelope_hash IS NULL AND NEW.regression_artifact_ciphertext_hash IS NULL AND NEW.regression_artifact_stage_generation IS NULL AND NEW.regression_artifact_stage_attempt IS NULL ) OR ( NEW.regression_report_hash IS NOT NULL AND NEW.regression_artifact_object_key IS NOT NULL AND NEW.regression_artifact_envelope_hash IS NOT NULL AND NEW.regression_artifact_ciphertext_hash IS NOT NULL AND NEW.regression_artifact_stage_generation IS NOT NULL AND NEW.regression_artifact_stage_attempt IS NOT NULL ) ) BEGIN SELECT RAISE(ABORT, 'ontology regression evidence tuple must be complete'); END
CREATE TRIGGER pattern_ontology_pipeline_runs_command_immutable BEFORE UPDATE ON pattern_ontology_pipeline_runs FOR EACH ROW WHEN OLD.run_id IS NOT NEW.run_id OR OLD.idempotency_key IS NOT NEW.idempotency_key OR OLD.corpus_release_id IS NOT NEW.corpus_release_id OR OLD.corpus_hash IS NOT NEW.corpus_hash OR OLD.candidate_ontology_version IS NOT NEW.candidate_ontology_version OR OLD.configuration_json IS NOT NEW.configuration_json OR OLD.configuration_hash IS NOT NEW.configuration_hash OR OLD.created_at IS NOT NEW.created_at BEGIN SELECT RAISE(ABORT, 'ontology pipeline command pins are immutable'); END
CREATE TRIGGER pattern_ontology_pipeline_runs_evidence_immutable BEFORE UPDATE ON pattern_ontology_pipeline_runs FOR EACH ROW WHEN (OLD.candidate_hash IS NOT NULL AND OLD.candidate_hash IS NOT NEW.candidate_hash) OR ( OLD.compilation_report_hash IS NOT NULL AND OLD.compilation_report_hash IS NOT NEW.compilation_report_hash ) OR ( OLD.evaluation_report_hash IS NOT NULL AND OLD.evaluation_report_hash IS NOT NEW.evaluation_report_hash ) OR ( OLD.regression_report_hash IS NOT NULL AND OLD.regression_report_hash IS NOT NEW.regression_report_hash ) OR (OLD.bundle_hash IS NOT NULL AND OLD.bundle_hash IS NOT NEW.bundle_hash) BEGIN SELECT RAISE(ABORT, 'ontology pipeline evidence hashes are immutable'); END
CREATE TRIGGER pattern_ontology_pipeline_runs_expire_failed_artifacts AFTER UPDATE OF stage, failed_artifact_expires_at ON pattern_ontology_pipeline_runs FOR EACH ROW WHEN OLD.stage IS NOT NEW.stage AND NEW.stage = 'failed' BEGIN UPDATE pattern_ontology_pipeline_artifacts SET expires_at = NEW.failed_artifact_expires_at WHERE run_id = NEW.run_id AND expires_at IS NULL AND deleted_at IS NULL; END
CREATE TRIGGER pattern_ontology_pipeline_runs_initial_state BEFORE INSERT ON pattern_ontology_pipeline_runs FOR EACH ROW WHEN NOT ( NEW.stage = 'reserved' AND NEW.stage_generation = 0 AND NEW.stage_cursor = 0 AND NEW.stage_attempt = 0 AND NEW.claim_token IS NULL AND NEW.lease_expires_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.failure_class IS NULL AND NEW.candidate_hash IS NULL AND NEW.compilation_report_hash IS NULL AND NEW.evaluation_report_hash IS NULL AND NEW.regression_report_hash IS NULL AND NEW.bundle_hash IS NULL AND NEW.failed_artifact_expires_at IS NULL AND NEW.finished_at IS NULL AND NEW.succeeded_at IS NULL AND NEW.failed_at IS NULL ) BEGIN SELECT RAISE(ABORT, 'new ontology pipeline run must start reserved'); END
CREATE TRIGGER pattern_ontology_pipeline_runs_no_delete BEFORE DELETE ON pattern_ontology_pipeline_runs FOR EACH ROW BEGIN SELECT RAISE(ABORT, 'ontology pipeline run cannot be deleted'); END
CREATE TRIGGER pattern_ontology_pipeline_runs_no_reuse BEFORE INSERT ON pattern_ontology_pipeline_runs FOR EACH ROW WHEN EXISTS ( SELECT 1 FROM pattern_ontology_pipeline_runs run WHERE run.run_id = NEW.run_id OR run.idempotency_key = NEW.idempotency_key OR run.candidate_ontology_version = NEW.candidate_ontology_version ) BEGIN SELECT RAISE(ABORT, 'ontology pipeline command identity cannot be reused'); END
CREATE TRIGGER pattern_ontology_pipeline_runs_stage_sequence BEFORE UPDATE ON pattern_ontology_pipeline_runs FOR EACH ROW WHEN NOT ( ( OLD.stage = NEW.stage AND OLD.stage_generation = NEW.stage_generation AND NEW.stage_cursor = OLD.stage_cursor AND ( ( OLD.claim_token IS NULL AND OLD.lease_expires_at IS NULL AND NEW.claim_token IS NULL AND NEW.lease_expires_at IS NULL AND NEW.stage_attempt = OLD.stage_attempt ) OR ( OLD.claim_token IS NULL AND OLD.lease_expires_at IS NULL AND NEW.claim_token IS NOT NULL AND NEW.lease_expires_at IS NOT NULL AND NEW.stage_attempt = OLD.stage_attempt AND NEW.dispatched_at IS NOT NULL AND ( OLD.dispatched_at IS NULL OR NEW.dispatched_at IS OLD.dispatched_at ) AND NEW.available_at IS OLD.available_at ) OR ( OLD.claim_token IS NOT NULL AND NEW.claim_token IS OLD.claim_token AND NEW.lease_expires_at IS OLD.lease_expires_at AND NEW.stage_attempt = OLD.stage_attempt AND NEW.dispatched_at IS OLD.dispatched_at AND NEW.available_at IS OLD.available_at ) OR ( OLD.claim_token IS NOT NULL AND OLD.lease_expires_at IS NOT NULL AND NEW.claim_token IS NULL AND NEW.lease_expires_at IS NULL AND NEW.stage_attempt IN (OLD.stage_attempt, OLD.stage_attempt + 1) AND NEW.dispatched_at IS NULL ) ) ) OR ( OLD.stage = NEW.stage AND OLD.stage IN ('generating', 'evaluating', 'regressing') AND NEW.stage_generation = OLD.stage_generation + 1 AND NEW.stage_cursor = OLD.stage_cursor + 1 AND NEW.stage_attempt = 0 AND NEW.claim_token IS NULL AND NEW.lease_expires_at IS NULL AND NEW.dispatched_at IS NULL ) OR ( NEW.stage_generation = OLD.stage_generation + 1 AND ( ( ( (OLD.stage = 'reserved' AND NEW.stage = 'corpus_reading') OR (OLD.stage = 'corpus_reading' AND NEW.stage = 'generating') OR (OLD.stage = 'generating' AND NEW.stage = 'compiling') OR (OLD.stage = 'compiling' AND NEW.stage = 'evaluating') OR (OLD.stage = 'evaluating' AND NEW.stage = 'regressing') OR (OLD.stage = 'regressing' AND NEW.stage = 'signing') OR (OLD.stage = 'signing' AND NEW.stage = 'ingesting') ) AND NEW.stage_cursor = 0 AND NEW.stage_attempt = 0 AND NEW.claim_token IS NULL AND NEW.lease_expires_at IS NULL AND NEW.dispatched_at IS NULL ) OR (OLD.stage = 'ingesting' AND NEW.stage = 'succeeded') OR ( OLD.stage NOT IN ('succeeded', 'failed') AND NEW.stage = 'failed' ) ) ) ) BEGIN SELECT RAISE(ABORT, 'invalid ontology pipeline stage transition'); END
CREATE TRIGGER pattern_ontology_pipeline_runs_terminal_after_artifacts BEFORE UPDATE OF stage, finished_at ON pattern_ontology_pipeline_runs FOR EACH ROW WHEN OLD.stage NOT IN ('succeeded', 'failed') AND NEW.stage IN ('succeeded', 'failed') AND unixepoch(NEW.finished_at) IS NOT NULL AND EXISTS ( SELECT 1 FROM pattern_ontology_pipeline_artifacts artifact WHERE artifact.run_id = NEW.run_id AND unixepoch(artifact.created_at) > unixepoch(NEW.finished_at) ) BEGIN SELECT RAISE(ABORT, 'ontology pipeline terminal timestamp precedes owned artifact'); END
CREATE TRIGGER pattern_ontology_pipeline_runs_terminal_immutable BEFORE UPDATE ON pattern_ontology_pipeline_runs FOR EACH ROW WHEN OLD.stage IN ('succeeded', 'failed') BEGIN SELECT RAISE(ABORT, 'terminal ontology pipeline run is immutable'); END
CREATE TRIGGER pattern_portrait_account_fence AFTER UPDATE OF status ON users WHEN NEW.status IN ('pending_deletion','deleted') BEGIN UPDATE pattern_portraits SET status = 'cancelled', graph_asset_id = NULL WHERE user_id = NEW.id; END
CREATE TRIGGER pattern_portrait_adaptive_identity_immutable BEFORE UPDATE OF chapter_count, protocol_version ON pattern_portraits WHEN NEW.chapter_count IS NOT OLD.chapter_count OR NEW.protocol_version IS NOT OLD.protocol_version BEGIN SELECT RAISE(ABORT, 'portrait count and protocol are immutable'); END
CREATE TRIGGER pattern_portrait_cancel_cleanup AFTER UPDATE OF status ON pattern_portraits WHEN NEW.status = 'cancelled' BEGIN UPDATE pattern_portrait_jobs SET status = 'cancelled', lease_hash = NULL, lease_expires_at = NULL WHERE portrait_id = NEW.id; UPDATE pattern_portrait_assets SET cleanup_at = COALESCE(cleanup_at, strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE portrait_id = NEW.id; END
CREATE TRIGGER pattern_portrait_consent_revoke_insert AFTER INSERT ON consents WHEN NEW.kind IN ('pattern_generation','account_processing') AND NEW.status != 'granted' BEGIN UPDATE pattern_portraits SET status = 'cancelled', graph_asset_id = NULL WHERE user_id = NEW.user_id AND status != 'ready'; END
CREATE TRIGGER pattern_portrait_consent_revoke_update AFTER UPDATE OF status ON consents WHEN NEW.kind IN ('pattern_generation','account_processing') AND NEW.status != 'granted' BEGIN UPDATE pattern_portraits SET status = 'cancelled', graph_asset_id = NULL WHERE user_id = NEW.user_id AND status != 'ready'; END
CREATE TRIGGER pattern_portrait_document_erasure AFTER DELETE ON pattern_documents BEGIN UPDATE pattern_portraits SET status = 'cancelled', graph_asset_id = NULL, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE pattern_id = OLD.id; UPDATE pattern_portrait_jobs SET status = 'cancelled', lease_hash = NULL, lease_expires_at = NULL WHERE portrait_id IN (SELECT id FROM pattern_portraits WHERE pattern_id = OLD.id); UPDATE pattern_portrait_assets SET cleanup_at = COALESCE(cleanup_at, strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE portrait_id IN (SELECT id FROM pattern_portraits WHERE pattern_id = OLD.id); END
CREATE TRIGGER pattern_portrait_jobs_chapter_insert BEFORE INSERT ON pattern_portrait_jobs WHEN NOT EXISTS ( SELECT 1 FROM pattern_portraits p WHERE p.id = NEW.portrait_id AND typeof(NEW.chapter_index) = 'integer' AND NEW.chapter_index >= 0 AND NEW.chapter_index < p.chapter_count ) BEGIN SELECT RAISE(ABORT, 'portrait chapter index is outside frozen count'); END
CREATE TRIGGER pattern_portrait_jobs_chapter_update BEFORE UPDATE OF portrait_id, chapter_index ON pattern_portrait_jobs WHEN NOT EXISTS ( SELECT 1 FROM pattern_portraits p WHERE p.id = NEW.portrait_id AND typeof(NEW.chapter_index) = 'integer' AND NEW.chapter_index >= 0 AND NEW.chapter_index < p.chapter_count ) BEGIN SELECT RAISE(ABORT, 'portrait chapter index is outside frozen count'); END
CREATE TRIGGER pattern_source_corpus_releases_identity_immutable BEFORE UPDATE ON pattern_source_corpus_releases FOR EACH ROW BEGIN SELECT RAISE(ABORT, 'registered ontology source corpus is immutable'); END
CREATE TRIGGER pattern_source_corpus_releases_no_delete BEFORE DELETE ON pattern_source_corpus_releases FOR EACH ROW BEGIN SELECT RAISE(ABORT, 'registered ontology source corpus cannot be deleted'); END
CREATE TRIGGER pattern_source_corpus_releases_no_reuse BEFORE INSERT ON pattern_source_corpus_releases FOR EACH ROW WHEN EXISTS ( SELECT 1 FROM pattern_source_corpus_releases corpus WHERE corpus.corpus_release_id = NEW.corpus_release_id OR corpus.corpus_hash = NEW.corpus_hash OR corpus.object_key = NEW.object_key ) BEGIN SELECT RAISE(ABORT, 'registered ontology source corpus identity cannot be reused'); END
CREATE TRIGGER portrait_automation_publish AFTER INSERT ON pattern_documents BEGIN INSERT OR IGNORE INTO portrait_start_outbox(id,user_id,pattern_id,grant_id,chart_id,status,created_at) SELECT 'ppstart_'||lower(hex(randomblob(16))),NEW.user_id,NEW.id,g.id,g.chart_id,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM portrait_automation_grants g JOIN chart_snapshots c ON c.id=g.chart_id AND c.user_id=g.user_id AND c.status='active' WHERE g.user_id=NEW.user_id AND g.chart_fingerprint_hash=NEW.chart_fingerprint_hash AND g.enabled=1; END
CREATE TRIGGER portrait_automation_withdraw AFTER UPDATE OF enabled ON portrait_automation_grants WHEN NEW.enabled=0 BEGIN UPDATE portrait_start_outbox SET status='cancelled' WHERE grant_id=NEW.id AND status='pending'; UPDATE portrait_mesh_jobs SET status='cancelled',lease_hash=NULL,lease_expires_at=NULL WHERE grant_id=NEW.id AND status!='complete'; UPDATE pattern_portrait_jobs SET status='cancelled',lease_hash=NULL,lease_expires_at=NULL WHERE status!='complete' AND portrait_id IN(SELECT id FROM pattern_portraits WHERE pattern_id IN(SELECT pattern_id FROM portrait_start_outbox WHERE grant_id=NEW.id)); UPDATE pattern_portraits SET status='failed' WHERE status IN('generating','failed') AND pattern_id IN(SELECT pattern_id FROM portrait_start_outbox WHERE grant_id=NEW.id); END
CREATE TRIGGER portrait_mesh_account_delete AFTER UPDATE OF status ON users WHEN NEW.status IN('pending_deletion','deleted') BEGIN UPDATE portrait_automation_grants SET enabled=0,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE user_id=NEW.id AND enabled=1; UPDATE portrait_start_outbox SET status='cancelled' WHERE user_id=NEW.id; UPDATE portrait_mesh_jobs SET status='cancelled',lease_hash=NULL,lease_expires_at=NULL WHERE user_id=NEW.id; END
CREATE TRIGGER portrait_mesh_cancel_cleanup AFTER UPDATE OF status ON portrait_mesh_jobs WHEN NEW.status='cancelled' BEGIN UPDATE portrait_mesh_assets SET cleanup_at=COALESCE(cleanup_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) WHERE job_id=NEW.id; END
CREATE TRIGGER portrait_mesh_consent_insert AFTER INSERT ON consents WHEN NEW.kind IN('pattern_generation','account_processing') AND NEW.status!='granted' BEGIN UPDATE portrait_automation_grants SET enabled=0,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE user_id=NEW.user_id AND enabled=1; UPDATE portrait_mesh_jobs SET status='cancelled',lease_hash=NULL,lease_expires_at=NULL WHERE user_id=NEW.user_id AND status!='complete'; END
CREATE TRIGGER portrait_mesh_consent_update AFTER UPDATE OF status ON consents WHEN NEW.kind IN('pattern_generation','account_processing') AND NEW.status!='granted' BEGIN UPDATE portrait_automation_grants SET enabled=0,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE user_id=NEW.user_id AND enabled=1; UPDATE portrait_mesh_jobs SET status='cancelled',lease_hash=NULL,lease_expires_at=NULL WHERE user_id=NEW.user_id AND status!='complete'; END
CREATE TRIGGER portrait_mesh_document_erasure AFTER DELETE ON pattern_documents BEGIN UPDATE portrait_start_outbox SET status='cancelled' WHERE pattern_id=OLD.id; UPDATE portrait_mesh_jobs SET status='cancelled',lease_hash=NULL,lease_expires_at=NULL WHERE portrait_id IN(SELECT id FROM pattern_portraits WHERE pattern_id=OLD.id); END
CREATE TRIGGER portrait_mesh_jobs_chapter_insert BEFORE INSERT ON portrait_mesh_jobs WHEN NOT EXISTS ( SELECT 1 FROM pattern_portraits p WHERE p.id = NEW.portrait_id AND typeof(NEW.chapter_index) = 'integer' AND NEW.chapter_index >= 0 AND NEW.chapter_index < p.chapter_count ) BEGIN SELECT RAISE(ABORT, 'portrait chapter index is outside frozen count'); END
CREATE TRIGGER portrait_mesh_jobs_chapter_update BEFORE UPDATE OF portrait_id, chapter_index ON portrait_mesh_jobs WHEN NOT EXISTS ( SELECT 1 FROM pattern_portraits p WHERE p.id = NEW.portrait_id AND typeof(NEW.chapter_index) = 'integer' AND NEW.chapter_index >= 0 AND NEW.chapter_index < p.chapter_count ) BEGIN SELECT RAISE(ABORT, 'portrait chapter index is outside frozen count'); END
CREATE TRIGGER portrait_mesh_parent_cancel AFTER UPDATE OF status ON pattern_portraits WHEN NEW.status='cancelled' BEGIN UPDATE portrait_mesh_jobs SET status='cancelled',lease_hash=NULL,lease_expires_at=NULL WHERE portrait_id=NEW.id; END
CREATE TRIGGER runtime_health_mesh_capture AFTER UPDATE OF status ON portrait_mesh_jobs WHEN NEW.status='complete' AND OLD.status!='complete' AND NEW.completed_at IS NOT NULL BEGIN INSERT OR IGNORE INTO runtime_health_capture VALUES('mesh',NEW.completed_at); END
CREATE TRIGGER runtime_health_portrait_capture AFTER UPDATE OF status ON pattern_portrait_jobs WHEN NEW.status='complete' AND OLD.status!='complete' AND NEW.completed_at IS NOT NULL BEGIN INSERT OR IGNORE INTO runtime_health_capture VALUES('portrait',NEW.completed_at); END
INSERT INTO pattern_ontology_pointer (id, active_version, updated_at) VALUES (1, NULL, '1970-01-01T00:00:00Z')
